  insert into quiz_options(question_id,option_text,is_correct,order_index) values (qq,$t$TRIG sends the sound pulse and ECHO receives the reflected pulse$t$,true,1),(qq,$t$They control the servo$t$,false,2),(qq,$t$They hold the sanitizer$t$,false,3),(qq,$t$TRIG supplies power and ECHO is ground$t$,false,4);
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 3: The ultrasonic sensor and the Arduino$t$,$t$Understand how the sensor detects distance and connect it to the Arduino.$t$,3) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$What is an ultrasonic sensor?$t$,$t$<p><strong>🎯 Objective:</strong> Explain how an ultrasonic sensor detects things.</p><p>An ultrasonic sensor measures distance without touching anything, and it needs a program to work. The common model, the <strong>HC-SR04</strong>, has 4 pins.</p><table><thead><tr><th>Sensor pin</th><th>Connects to</th><th>Job</th></tr></thead><tbody><tr><td>VCC</td><td>5V</td><td>Powers the sensor</td></tr><tr><td>GND</td><td>GND</td><td>Completes the circuit</td></tr><tr><td>TRIG</td><td>Digital pin 9 (can be any digital pin)</td><td>Sends out an ultrasonic pulse</td></tr><tr><td>ECHO</td><td>Digital pin 10 (can be any digital pin)</td><td>Receives the reflected pulse</td></tr></tbody></table><p>The sensor sends out sound waves from the TRIG pin. The waves bounce off your hand and return to the ECHO pin. The Arduino uses the time taken to work out how far away your hand is.</p>$t$,null,$t$Sound goes out, bounces back, and the Arduino measures the time.$t$,1,10),
    (m,$t$Connect the sensor to the Arduino$t$,$t$<p><strong>🎯 Objective:</strong> Wire the ultrasonic sensor through the breadboard.</p><h3>You need</h3><ul><li>Ultrasonic sensor</li><li>Arduino Uno</li><li>Pin-to-pin and pin-to-port jumper wires</li><li>Breadboard</li></ul><h3>Steps</h3><ol><li>Power the breadboard: use two pin-to-pin jumper wires to connect the Arduino's <strong>GND</strong> and <strong>5V</strong> to the long power strips of the breadboard.</li><li>Using a pin-to-port jumper wire, connect the 5V strip of the breadboard to the sensor's <strong>VCC</strong> pin.</li><li>Connect the GND strip of the breadboard to the sensor's <strong>GND</strong> pin.</li><li>Connect the sensor's <strong>TRIG</strong> and <strong>ECHO</strong> pins to Arduino digital pins <strong>9</strong> and <strong>10</strong>, through the breadboard.</li></ol><p><em>📷 Picture to be added: the ultrasonic sensor connected through the breadboard to pins 9 and 10</em></p><p><strong>⚠ Caution:</strong> Double-check your connections. If VCC and GND are reversed you could damage the sensor.</p>$t$,null,$t$Use different colours for different wires.$t$,2,15),
    (m,$t$Wiring tips$t$,$t$<p><strong>🎯 Objective:</strong> Keep your wiring neat and safe.</p><ul><li>Use different coloured jumper wires, for example red for VCC, black for GND, yellow for TRIG and green for ECHO.</li><li>Make sure every wire is pushed firmly into the correct pin.</li><li>Ask your tutor to check your circuit before you power it.</li></ul>$t$,null,$t$Neat wiring is easier to fix.$t$,3,6);
