  insert into quiz_options(question_id,option_text,is_correct,order_index) values (qq,$t$Nothing at all$t$,false,1),(qq,$t$The sensor could be damaged$t$,true,2),(qq,$t$The sanitizer comes out faster$t$,false,3),(qq,$t$The sensor works better$t$,false,4);
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 4: Connecting the servo motor$t$,$t$Learn how a servo motor works and connect it to the Arduino.$t$,4) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$What is a servo motor?$t$,$t$<p><strong>🎯 Objective:</strong> Explain what a servo motor is and what it does in this project.</p><p>A servo motor is a special kind of motor that can turn to a certain angle and stop there, instead of spinning all the time. Think of a robot's arm: it can move to a specific position and hold it. In our dispenser, the servo moves the pen that presses the sanitizer cap.</p>$t$,null,$t$A servo turns to an angle and holds it.$t$,1,8),
    (m,$t$The servo's three wires$t$,$t$<p><strong>🎯 Objective:</strong> Identify the three wires of a servo motor and their jobs.</p><table><thead><tr><th>Servo wire</th><th>Colour</th><th>Connects to</th><th>Job</th></tr></thead><tbody><tr><td>VCC (power)</td><td>Red</td><td>5V</td><td>Supplies power to the servo</td></tr><tr><td>GND (ground)</td><td>Brown</td><td>GND</td><td>Completes the circuit</td></tr><tr><td>Signal</td><td>Orange</td><td>Digital pin 3</td><td>Carries control signals from the Arduino to the servo</td></tr></tbody></table>$t$,null,$t$Red = power. Brown = ground. Orange = signal.$t$,2,8),
    (m,$t$Connect the servo to the Arduino$t$,$t$<p><strong>🎯 Objective:</strong> Wire the servo through the breadboard.</p><h3>You need</h3><ul><li>Servo motor</li><li>Arduino Uno</li><li>Pin-to-pin and pin-to-port jumper wires</li><li>Breadboard</li></ul><h3>Steps</h3><ol><li>Connect the servo's <strong>red</strong> wire to the 5V strip and the <strong>brown</strong> wire to the GND strip of the breadboard.</li><li>Connect the servo's <strong>orange</strong> (signal) wire <strong>directly</strong> to digital pin <strong>3</strong> of the Arduino.</li></ol><p><strong>⚠ Caution:</strong> The orange signal wire must go directly to the Arduino, not through the breadboard power strips.</p><p><em>📷 Picture to be added: the servo wired to the breadboard and to pin 3</em></p>$t$,null,$t$Orange wire straight to pin 3.$t$,3,15),
    (m,$t$How the Arduino moves the servo$t$,$t$<p><strong>🎯 Objective:</strong> Explain how the Arduino tells the servo where to turn.</p><p>The Arduino talks to the servo by sending tiny electrical messages very quickly. Each message tells the servo how far to turn: a little, halfway or all the way. The servo listens and moves its arm to the right spot, like pointing in a direction when someone tells you to.</p><p>So the Arduino is the brain giving instructions, and the servo is the arm following them. The type of signal used is called <strong>PWM (pulse width modulation)</strong>.</p>$t$,null,$t$Arduino = brain. Servo = arm.$t$,4,8);
