  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 8: Testing and troubleshooting$t$,$t$Test the project, find mistakes and fix them like a detective.$t$,8) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Testing and debugging$t$,$t$<p><strong>🎯 Objective:</strong> Test your dispenser and find the mistakes that stop it working.</p><h3>You need</h3><ul><li>A fully assembled dispenser with everything well connected</li><li>Your code, checked against your teacher's version</li></ul><h3>Step 1: Testing</h3><p>Testing means trying out your project to see if it works. Plug in your Arduino, place your hand in front of the ultrasonic sensor and watch what happens.</p><h3>Step 2: Debugging</h3><p>Debugging means finding the small mistakes that stop your project working. Ask yourself:</p><ul><li>Did I connect all the wires to the right places?</li><li>Is my servo motor getting power?</li><li>Is my code correct?</li><li>Is my sensor facing the right direction?</li></ul><p>Check one thing at a time to find what is wrong.</p>$t$,null,$t$Check one thing at a time.$t$,1,12),
    (m,$t$Troubleshooting and testing again$t$,$t$<p><strong>🎯 Objective:</strong> Fix the problems you found and test again.</p><h3>Step 3: Troubleshooting</h3><p>Troubleshooting means fixing the problems you found.</p><ul><li><strong>The servo does not move:</strong> check it is connected properly and the wires are tight.</li><li><strong>The sensor does not sense your hand:</strong> make sure it faces the right way and is not blocked.</li><li><strong>The sanitizer does not come out:</strong> check the pen or stick is pressing the cap properly.</li><li><strong>Nothing works:</strong> check the Arduino is powered on and the USB cable is plugged in.</li></ul><h3>Step 4: Test again</h3><p>After fixing everything, test one more time. If it works, you have successfully debugged and fixed your project.</p><p>Testing, debugging and troubleshooting are like being a detective for robots: you look for clues, find what is wrong and fix it.</p>$t$,null,$t$Test, debug, troubleshoot, test again.$t$,2,12);
