  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 9: Improving the design$t$,$t$Make your dispenser better and make it your own.$t$,9) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Improve and decorate$t$,$t$<p><strong>🎯 Objective:</strong> Change your design to improve how it works, and try new features.</p><h3>You need</h3><ul><li>A well-working, complete automatic sanitizer</li><li>Extra materials: LEDs, a buzzer, other sensors</li></ul><ul><li>Decorate the sanitizer to make it unique.</li><li>Show how it works automatically.</li><li>Share the challenges you had and how you solved them.</li><li>Try a new feature, such as an LED that lights when sanitizer is given or a buzzer that beeps.</li></ul><h3>Skills you gained</h3><ul><li>Teamwork and communication</li><li>Basic electronics and coding</li><li>Problem-solving and creativity</li><li>Confidence in building technology</li></ul><p>The automatic sanitizer shows how curiosity, teamwork and technology can make life easier and cleaner. With simple tools and good ideas, you can invent useful solutions for everyday life.</p>$t$,null,$t$Small improvements make a big difference.$t$,1,20);
  insert into modules(course_id,title,description,order_index) values (c,$t$Lesson 10: Presentation and reflection$t$,$t$Present your dispenser and reflect on your project.$t$,10) returning id into m;
  insert into lessons(module_id,title,content,code_example,tip_text,order_index,estimated_minutes) values
    (m,$t$Prepare your presentation$t$,$t$<p><strong>🎯 Objective:</strong> Get ready to present your automatic sanitizer.</p><h3>You need</h3><ul><li>Your completed automatic sanitizer</li><li>A laptop to show your program in mBlock</li><li>A project display table or desk</li></ul><p>Each group will showcase its automatic sanitizer and explain how it works. Describe what each part does and how the program controls the sanitizer.</p>$t$,null,$t$Know what each part does.$t$,1,15),
    (m,$t$Present and reflect$t$,$t$<p><strong>🎯 Objective:</strong> Present with confidence, explain your design and program, and give kind feedback.</p><h3>Each group should</h3><ol><li>Introduce your project: group members and project title.</li><li>Show your model and describe how you designed it.</li><li>Explain the program: how the Arduino, servo motor and ultrasonic sensor work together.</li><li>Demonstrate the sanitizer in action, if possible.</li><li>Conclude by sharing one thing you learned.</li></ol><p>Listen to other groups and give constructive feedback on their projects.</p><h3>Check yourself</h3><ul><li>Did every team member take part?</li><li>Did you explain the design and the programming?</li><li>What is one thing you would improve?</li></ul>$t$,null,$t$Share one thing you learned.$t$,2,20);
